mapper.select:
SELECT activity_refund.refund_no, activity_order.order_no, activity_refund.activity_id, activity.title AS activity_title, activity_refund.user_id, portal_user.username, activity_refund.amount_fen, activity_refund.reason_type, activity_refund.reason, activity_refund.status, activity_refund.channel_refund_no, activity_refund.refund_time, activity_refund.create_time FROM activity_refund LEFT JOIN activity_order ON activity_order.id = activity_refund.order_id LEFT JOIN activity ON activity.id = activity_refund.activity_id LEFT JOIN portal_user ON portal_user.id = activity_refund.user_id WHERE activity_refund.deleted_flag = 0
AND activity_refund.status = #{queryForm.status}
AND activity_refund.activity_id = #{queryForm.activityId}
AND activity_refund.user_id = #{queryForm.userId}
AND (activity_refund.refund_no LIKE CONCAT('%', #{queryForm.keyword}, '%') OR activity_order.order_no LIKE CONCAT('%', #{queryForm.keyword}, '%') OR portal_user.username LIKE CONCAT('%', #{queryForm.keyword}, '%'))
AND activity_refund.create_time >= #{queryForm.beginCreateTime}
AND activity_refund.create_time <= #{queryForm.endCreateTime}
ORDER BY activity_refund.id DESC
